_id"><option value="">No preference</option>@foreach($personnel as $p)<option value="{{$p->id}}">{{$p->user->name}} — {{$p->designation}}</option>@endforeach</select><span class="text-sm text-slate-500">A preference is not an assignment.</span></label><label class="mt-3 block">Photos or short videos, up to {{ config('work_orders.attachments.max_count') }} (10 MB each)<input class="mt-1 w-full" type="file" name="attachments[]" multiple accept="image/jpeg,image/png,image/webp,video/mp4"></label><button class="mt-5 rounded bg-blue-700 px-4 py-2 text-white">Submit request</button></form><script>const campus=document.querySelector('#campus'),building=document.querySelector('#building'),floor=document.querySelector('#floor'),location=document.querySelector('#location');function filter(select,key,value){[...select.options].forEach(o=>o.hidden=!!o.dataset[key]&&o.dataset[key]!==value);if(select.selectedOptions[0]?.hidden)select.value='';}function sync(){filter(building,'campus',campus.value);filter(floor,'building',building.value);filter(location,'building',building.value);if(floor.value)filter(location,'floor',floor.value);}campus.onchange=sync;building.onchange=sync;floor.onchange=sync;sync();</script>@endsection
